    private void btnGuardarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnGuardarActionPerformed
        try {

        String nombre = txtNombre.getText().trim();
        String telefono = txtTelefono.getText().trim();
        String correo = txtCorreo.getText().trim();
        String direccion = txtDireccion.getText().trim();

        if (nombre.isEmpty()) {
            JOptionPane.showMessageDialog(
                    this,
                    "El nombre del proveedor es obligatorio."
            );
            return;
        }

        if (!correo.isEmpty() &&
                !correo.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$")) {

            JOptionPane.showMessageDialog(
                    this,
                    "Ingrese un correo electrónico válido."
            );
            return;
        }

        Proveedor proveedor = new Proveedor(
                0,
                nombre,
                telefono,
                correo,
                direccion
        );

        ProveedorDatos datos = new ProveedorDatos();

        if (datos.agregar(proveedor)) {

            JOptionPane.showMessageDialog(
                    this,
                    "Proveedor registrado correctamente."
            );

            cargarProveedores();

            txtIdProveedor.setText("");
            txtNombre.setText("");
            txtTelefono.setText("");
            txtCorreo.setText("");
            txtDireccion.setText("");

            tblProveedores.clearSelection();

        } else {

            JOptionPane.showMessageDialog(
                    this,
                    "No se pudo registrar el proveedor."
            );
        }

    } catch (SQLException e) {

        JOptionPane.showMessageDialog(
                this,
                "Error al registrar proveedor: " + e.getMessage(),
                "Error de base de datos",
                JOptionPane.ERROR_MESSAGE
        );
    }
    }//GEN-LAST:event_btnGuardarActionPerformed

    private void tblProveedoresMouseClicked(java.awt.event.MouseEvent evt) {//GEN-FIRST:event_tblProveedoresMouseClicked
        int fila = tblProveedores.getSelectedRow();

    if (fila == -1) {
        return;
    }

    int filaModelo = tblProveedores.convertRowIndexToModel(fila);

    txtIdProveedor.setText(
            tblProveedores.getModel().getValueAt(filaModelo, 0).toString()
    );

    txtNombre.setText(
            tblProveedores.getModel().getValueAt(filaModelo, 1).toString()
    );

    txtTelefono.setText(
            String.valueOf(tblProveedores.getModel().getValueAt(filaModelo, 2) == null
                    ? "" : tblProveedores.getModel().getValueAt(filaModelo, 2))
    );

    txtCorreo.setText(
            String.valueOf(tblProveedores.getModel().getValueAt(filaModelo, 3) == null
                    ? "" : tblProveedores.getModel().getValueAt(filaModelo, 3))
    );

    txtDireccion.setText(
            String.valueOf(tblProveedores.getModel().getValueAt(filaModelo, 4) == null
                    ? "" : tblProveedores.getModel().getValueAt(filaModelo, 4))
    );
    }//GEN-LAST:event_tblProveedoresMouseClicked

    private void btnEditarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnEditarActionPerformed
        try {

        if (txtIdProveedor.getText().trim().isEmpty()) {
            JOptionPane.showMessageDialog(
                    this,
                    "Seleccione un proveedor de la tabla para editar."
            );
            return;
        }

        int idProveedor = Integer.parseInt(
                txtIdProveedor.getText().trim()
        );

        String nombre = txtNombre.getText().trim();
        String telefono = txtTelefono.getText().trim();
        String correo = txtCorreo.getText().trim();
        String direccion = txtDireccion.getText().trim();

        if (nombre.isEmpty()) {
            JOptionPane.showMessageDialog(
                    this,
                    "El nombre del proveedor es obligatorio."
            );
            return;
        }

        if (!correo.isEmpty() &&
                !correo.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$")) {

            JOptionPane.showMessageDialog(
                    this,
                    "Ingrese un correo electrónico válido."
            );
            return;
        }

        int confirmacion = JOptionPane.showConfirmDialog(
                this,
                "¿Desea guardar los cambios de este proveedor?",
                "Confirmar modificación",
                JOptionPane.YES_NO_OPTION
        );

        if (confirmacion != JOptionPane.YES_OPTION) {
            return;
        }

        Proveedor proveedor = new Proveedor(
                idProveedor,
                nombre,
                telefono,
                correo,
                direccion
        );

        ProveedorDatos datos = new ProveedorDatos();

        if (datos.modificar(proveedor)) {

            JOptionPane.showMessageDialog(
                    this,
                    "Proveedor actualizado correctamente."
            );

            cargarProveedores();

            txtIdProveedor.setText("");
            txtNombre.setText("");
            txtTelefono.setText("");
            txtCorreo.setText("");
            txtDireccion.setText("");

            tblProveedores.clearSelection();

        } else {

            JOptionPane.showMessageDialog(
                    this,
                    "No se pudo actualizar el proveedor."
            );
        }

    } catch (SQLException | NumberFormatException e) {

        JOptionPane.showMessageDialog(
                this,
                "Error al modificar proveedor: " + e.getMessage(),
                "Error",
                JOptionPane.ERROR_MESSAGE
        );
    }
    }//GEN-LAST:event_btnEditarActionPerformed

    private void btnEliminarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnEliminarActionPerformed
         try {

        if (txtIdProveedor.getText().trim().isEmpty()) {
            JOptionPane.showMessageDialog(
                    this,
                    "Seleccione un proveedor de la tabla para eliminar."
            );
            return;
        }

        int idProveedor = Integer.parseInt(
                txtIdProveedor.getText().trim()
        );

        String nombre = txtNombre.getText().trim();

        int confirmacion = JOptionPane.showConfirmDialog(
                this,
                "¿Está seguro de eliminar al proveedor:\n"
                + nombre + "?",
                "Confirmar eliminación",
                JOptionPane.YES_NO_OPTION,
                JOptionPane.WARNING_MESSAGE
        );

        if (confirmacion != JOptionPane.YES_OPTION) {
            return;
        }

        ProveedorDatos datos = new ProveedorDatos();

        if (datos.eliminar(idProveedor)) {

            JOptionPane.showMessageDialog(
                    this,
                    "Proveedor eliminado correctamente."
            );

            cargarProveedores();

            txtIdProveedor.setText("");
            txtNombre.setText("");
            txtTelefono.setText("");
            txtCorreo.setText("");
            txtDireccion.setText("");

            tblProveedores.clearSelection();

        } else {

            JOptionPane.showMessageDialog(
                    this,
                    "No se pudo eliminar el proveedor."
            );
        }

    } catch (SQLException e) {

        JOptionPane.showMessageDialog(
                this,
                "No se pudo eliminar el proveedor.\n"
                + "Puede tener compras asociadas.\n\n"
                + "Detalle: " + e.getMessage(),
                "Error de base de datos",
                JOptionPane.ERROR_MESSAGE
        );

    } catch (NumberFormatException e) {

        JOptionPane.showMessageDialog(
                this,
                "El ID del proveedor no es válido.",
                "Error",
                JOptionPane.ERROR_MESSAGE
        );
    }
    }//GEN-LAST:event_btnEliminarActionPerformed

    private void btnBuscarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnBuscarActionPerformed
        try {

        String entrada = JOptionPane.showInputDialog(
                this,
                "Ingrese el ID del proveedor que desea buscar:",
                "Buscar proveedor",
                JOptionPane.QUESTION_MESSAGE
        );

        if (entrada == null) {
            return;
        }

        entrada = entrada.trim();

        if (entrada.isEmpty()) {
            JOptionPane.showMessageDialog(
                    this,
                    "Debe ingresar un ID."
            );
            return;
        }

        int idProveedor = Integer.parseInt(entrada);

        if (idProveedor <= 0) {
            JOptionPane.showMessageDialog(
                    this,
                    "Ingrese un ID mayor que cero."
            );
            return;
        }

        ProveedorDatos datos = new ProveedorDatos();
        Proveedor proveedor = datos.buscar(idProveedor);

        if (proveedor != null) {

            txtIdProveedor.setText(
                    String.valueOf(proveedor.getIdProveedor())
            );

            txtNombre.setText(proveedor.getNombre());

            txtTelefono.setText(
                    proveedor.getTelefono() == null
                    ? "" : proveedor.getTelefono()
            );

            txtCorreo.setText(
                    proveedor.getCorreo() == null
                    ? "" : proveedor.getCorreo()
            );

            txtDireccion.setText(
                    proveedor.getDireccion() == null
                    ? "" : proveedor.getDireccion()
            );

            tblProveedores.clearSelection();

            for (int i = 0; i < tblProveedores.getRowCount(); i++) {

                int idTabla = Integer.parseInt(
                        tblProveedores.getValueAt(i, 0).toString()
                );

                if (idTabla == idProveedor) {

                    tblProveedores.setRowSelectionInterval(i, i);

                    tblProveedores.scrollRectToVisible(
                            tblProveedores.getCellRect(i, 0, true)
                    );

                    break;
                }
            }

            JOptionPane.showMessageDialog(
                    this,
                    "Proveedor encontrado correctamente."
            );

        } else {

            JOptionPane.showMessageDialog(
                    this,
                    "No existe un proveedor con el ID " + idProveedor
            );
        }

    } catch (NumberFormatException e) {

        JOptionPane.showMessageDialog(
                this,
                "Ingrese un ID numérico válido.",
                "Dato incorrecto",
                JOptionPane.WARNING_MESSAGE
        );

    } catch (java.sql.SQLException e) {

        JOptionPane.showMessageDialog(
                this,
                "Error al buscar proveedor: " + e.getMessage(),
                "Error de base de datos",
                JOptionPane.ERROR_MESSAGE
        );
    }
    }//GEN-LAST:event_btnBuscarActionPerformed

