    private void btnIrComprasActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnIrComprasActionPerformed
        java.awt.Container contenedor = getParent();

    while (contenedor != null
            && !(contenedor instanceof FrmPrincipal)) {

        contenedor = contenedor.getParent();
    }

    if (contenedor instanceof FrmPrincipal) {

        FrmPrincipal principal = (FrmPrincipal) contenedor;

        javax.swing.JPanel panelContenido =
                (javax.swing.JPanel) getParent();

        panelContenido.removeAll();
        panelContenido.setLayout(new java.awt.BorderLayout());

        panelContenido.add(
                new PnlCompras(),
                java.awt.BorderLayout.CENTER
        );

        panelContenido.revalidate();
        panelContenido.repaint();
    }
    }//GEN-LAST:event_btnIrComprasActionPerformed

private void cargarProveedores() {

    DefaultTableModel modelo = new DefaultTableModel(
            new Object[]{
                "ID", "Nombre", "Teléfono",
                "Correo", "Dirección"
            }, 0
    ) {
        @Override
        public boolean isCellEditable(int fila, int columna) {
            return false;
        }
    };

    try {

        ProveedorDatos datos = new ProveedorDatos();

        for (Proveedor proveedor : datos.listar()) {

            modelo.addRow(new Object[]{
                proveedor.getIdProveedor(),
                proveedor.getNombre(),
                proveedor.getTelefono(),
                proveedor.getCorreo(),
                proveedor.getDireccion()
            });
        }

        tblProveedores.setModel(modelo);

    } catch (SQLException e) {

        JOptionPane.showMessageDialog(
                this,
                "Error al cargar proveedores: " + e.getMessage(),
                "Error de base de datos",
                JOptionPane.ERROR_MESSAGE
        );
    }
}

private void limpiarCampos() {

    txtIdProveedor.setText("");
    txtNombre.setText("");
    txtTelefono.setText("");
    txtCorreo.setText("");
    txtDireccion.setText("");

    tblProveedores.clearSelection();

    txtNombre.requestFocusInWindow();
}


